import { useEffect, useState } from 'react'
import {
  Modal,
  ModalTrigger,
  ModalContent,
  ModalHeader,
  ModalTitle,
  ModalDescription,
  ModalBody,
  ModalFooter,
  ModalClose,
} from '@components/ui/Modal'
import { openModal, openModalAsync } from '@components/overlay/modal'

// ModalTrigger：声明式，内部自己管开关
<Modal size="md">
  <ModalTrigger asChild>
    <button type="button">打开弹窗</button>
  </ModalTrigger>
  <ModalContent>
    <ModalHeader>
      <ModalTitle>标题</ModalTitle>
      <ModalDescription>描述</ModalDescription>
    </ModalHeader>
    <ModalBody>内容</ModalBody>
    <ModalFooter>
      <ModalClose asChild>
        <button type="button">关闭</button>
      </ModalClose>
    </ModalFooter>
  </ModalContent>
</Modal>

// open / onOpenChange：受控
function Controlled() {
  const [open, setOpen] = useState(false)
  return (
    <>
      <button type="button" onClick={() => setOpen(true)}>打开</button>
      <Modal size="md" open={open} onOpenChange={setOpen}>
        <ModalContent>
          <ModalHeader>
            <ModalTitle>受控</ModalTitle>
          </ModalHeader>
        </ModalContent>
      </Modal>
    </>
  )
}

// size：sm / md / lg，只作用于 Dialog
<Modal size="lg" open={open} onOpenChange={setOpen}>
  <ModalContent />
</Modal>

// openModal：根上已挂 OverlayProvider
openModal({
  size: 'sm',
  children: ({ close }) => (
    <>
      <ModalHeader>
        <ModalTitle>提示</ModalTitle>
      </ModalHeader>
      <ModalFooter>
        <button type="button" onClick={close}>知道了</button>
      </ModalFooter>
    </>
  ),
})

// openModalAsync：打开时拉数据，关闭 abort；确认后再发请求
type DeleteDraftResult = { deleted: true; title: string } | false

function DeleteDraftDialog({
  draftId,
  close,
}: {
  draftId: string
  close: (value?: DeleteDraftResult) => void
}) {
  const [title, setTitle] = useState<string | null>(null)

  useEffect(() => {
    const ac = new AbortController()
    fetch(`/api/drafts/${draftId}`, { signal: ac.signal })
      .then((res) => res.json())
      .then((draft) => setTitle(draft.title))
    return () => ac.abort()
  }, [draftId])

  async function onConfirm() {
    if (!title) return
    await fetch(`/api/drafts/${draftId}`, { method: 'DELETE' })
    close({ deleted: true, title })
  }

  return (
    <>
      <ModalHeader>
        <ModalTitle>删除草稿？</ModalTitle>
        <ModalDescription>打开拉标题；关掉 abort。确认后再删除。</ModalDescription>
      </ModalHeader>
      <ModalBody>{title ? `将永久删除「${title}」` : '正在加载…'}</ModalBody>
      <ModalFooter>
        <button type="button" onClick={() => close(false)}>取消</button>
        <button type="button" disabled={!title} onClick={() => void onConfirm()}>
          确认删除
        </button>
      </ModalFooter>
    </>
  )
}

const result = await openModalAsync<DeleteDraftResult>({
  size: 'sm',
  children: ({ close }) => (
    <DeleteDraftDialog draftId="draft-1" close={close} />
  ),
})

